const IMG=[[1,1,1,1,1],[1,1,9,9,9],[1,1,9,9,9],[1,1,9,9,9],[1,1,1,1,1]];
const K={vertical:[[1,0,-1],[1,0,-1],[1,0,-1]],horizontal:[[1,1,1],[0,0,0],[-1,-1,-1]],blur:[[1,1,1],[1,1,1],[1,1,1]]};
const NAME={vertical:"Vertical edges: each row 1, 0, \u22121",horizontal:"Horizontal edges: rows 1s, 0s, \u22121s",blur:"Box blur: all weights 1, then sum \u00f7 9"};
function fm(v){return v<0?"\u2212"+Math.abs(v):String(v);}
function sumAt(k,r,c){let s=0;for(let m=0;m<3;m++)for(let n=0;n<3;n++)s+=IMG[r+m][c+n]*k[m][n];return s;}
export function evaluate({inputs}){
 const kind=K[inputs.kernel]?inputs.kernel:"vertical";
 const k=K[kind];const blur=kind==="blur";
 const r=sdk.clamp(Math.round(inputs.row),0,2),c=sdk.clamp(Math.round(inputs.col),0,2);
 const o=[];
 o.push(sdk.text("t_img",160,50,"Input image (5 \u00d7 5)",{align:"middle"}));
 o.push(sdk.text("t_prod",527,50,"Pixel \u00d7 weight = product",{align:"middle"}));
 o.push(sdk.text("t_out",880,50,"Output map (3 \u00d7 3)",{align:"middle"}));
 for(let i=0;i<5;i++)for(let j=0;j<5;j++){
  const inW=i>=r&&i<r+3&&j>=c&&j<c+3;
  o.push(sdk.box("px_"+i+"_"+j,30+j*52,80+i*52,50,50,{text:String(IMG[i][j]),role:inW?"input":"neutral",opacity:inW?1:0.6}));
 }
 let s=0;
 for(let m=0;m<3;m++)for(let n=0;n<3;n++){
  const p=IMG[r+m][c+n],w=k[m][n],pr=p*w;s+=pr;
  o.push(sdk.box("pr_"+m+"_"+n,340+n*126,80+m*58,120,52,{text:p+" \u00d7 "+fm(w)+" = "+fm(pr),role:pr===0?"neutral":"code"}));
 }
 const out=blur?s/9:s;
 for(let i=0;i<3;i++)for(let j=0;j<3;j++){
  const sv=sumAt(k,i,j);const v=blur?sdk.format(sv/9,2):fm(sv);
  const cur=i===r&&j===c;
  o.push(sdk.box("out_"+i+"_"+j,775+j*72,80+i*58,68,52,{text:v,role:cur?"output":"neutral",opacity:cur?1:0.55}));
 }
 o.push(sdk.arrow("a1",296,167,334,167));
 o.push(sdk.arrow("a2",718,167,768,167));
 const sumTxt=blur?("Sum = "+fm(s)+", \u00f7 9 = "+sdk.format(out,2)+" \u2192 output["+r+","+c+"]"):("Sum of products = "+fm(s)+" \u2192 output["+r+","+c+"]");
 o.push(sdk.text("sum",527,290,sumTxt,{align:"middle",role:"output"}));
 o.push(sdk.text("kname",527,320,NAME[kind],{align:"middle"}));
 o.push(sdk.math("formula",540,400,"O[i,j]=\\sum_{m=0}^{2}\\sum_{n=0}^{2} I[i+m,\\,j+n]\\,K[m,n]"+(blur?"\\;/\\;9":""),{align:"middle"}));
 o.push(sdk.text("note",540,450,"3 window positions across \u00d7 3 down = 3 \u00d7 3 output (stride 1, no padding, no bias, kernel not flipped)",{align:"middle"}));
 return {frame:{width:1080,height:500,objects:o,readouts:[{id:"out_value",value:out},{id:"prod_sum",value:s}]},quantities:{output:out,sum:s,row:r,col:c}};
}

